//! Atomic projection of the pipeline's grouping policy into stored membership and evidence.

use sqlx::{Postgres, Transaction};

use crate::domain::models::{
    entity_ingestion::EntityIngestionError,
    funder::FunderId,
    funder_grouping::{GroupingFunder, build_funder_groups},
};

use super::ExposedDatabase;

impl ExposedDatabase {
    /// Rebuilds grouping for every persisted identity without replaying ingestion artifacts.
    ///
    /// # Errors
    /// Returns database or grouping-policy errors. A failed refresh preserves the previous projection.
    pub async fn refresh_funder_groups(&self) -> Result<usize, EntityIngestionError> {
        let mut tx = self.pool().begin().await.map_err(db_error)?;
        lock_declaration_loader(&mut tx).await?;
        let count = replace_funder_groups(&mut tx).await?;
        tx.commit().await.map_err(db_error)?;
        Ok(count)
    }
}

pub(super) async fn lock_declaration_loader(
    tx: &mut Transaction<'_, Postgres>,
) -> Result<(), EntityIngestionError> {
    sqlx::query!("SELECT pg_advisory_xact_lock(hashtext('exposed.declaration-loader'))")
        .execute(&mut **tx)
        .await
        .map_err(db_error)?;
    Ok(())
}

pub(super) async fn replace_funder_groups(
    tx: &mut Transaction<'_, Postgres>,
) -> Result<usize, EntityIngestionError> {
    let rows = sqlx::query!("SELECT id, funder_name FROM exposed.funders ORDER BY id")
        .fetch_all(&mut **tx)
        .await
        .map_err(db_error)?;
    let aliases = sqlx::query!("SELECT funder_id, funder_alias FROM exposed.funder_aliases ORDER BY funder_id, funder_alias")
        .fetch_all(&mut **tx).await.map_err(db_error)?;
    let mut by_id = std::collections::BTreeMap::<_, Vec<_>>::new();
    for alias in aliases {
        by_id
            .entry(alias.funder_id)
            .or_default()
            .push(alias.funder_alias);
    }
    let funders: Vec<_> = rows
        .into_iter()
        .map(|row| GroupingFunder {
            id: FunderId::new(row.id),
            name: row.funder_name,
            aliases: by_id.remove(&row.id).unwrap_or_default(),
        })
        .collect();
    let groups = build_funder_groups(&funders).map_err(db_error)?;
    sqlx::query!("DELETE FROM exposed.funder_alias_links")
        .execute(&mut **tx)
        .await
        .map_err(db_error)?;
    sqlx::query!("DELETE FROM exposed.funder_family_links")
        .execute(&mut **tx)
        .await
        .map_err(db_error)?;
    sqlx::query!("DELETE FROM exposed.funder_alias_groups")
        .execute(&mut **tx)
        .await
        .map_err(db_error)?;
    for (id, group) in &groups.memberships {
        sqlx::query!(
            "INSERT INTO exposed.funder_alias_groups (funder_id, group_id) VALUES ($1, $2)",
            id.value(),
            group.value()
        )
        .execute(&mut **tx)
        .await
        .map_err(db_error)?;
    }
    for link in groups.alias_links {
        sqlx::query!("INSERT INTO exposed.funder_alias_links (left_funder_id, right_funder_id, normalized_alias, left_alias, right_alias) VALUES ($1, $2, $3, $4, $5)", link.left_funder_id.value(), link.right_funder_id.value(), link.normalized_alias, link.left_alias, link.right_alias)
            .execute(&mut **tx).await.map_err(db_error)?;
    }
    for link in groups.family_links {
        sqlx::query!("INSERT INTO exposed.funder_family_links (left_funder_id, right_funder_id, family_key, left_name, right_name) VALUES ($1, $2, $3, $4, $5)", link.left_funder_id.value(), link.right_funder_id.value(), link.family_key, link.left_name, link.right_name)
            .execute(&mut **tx).await.map_err(db_error)?;
    }
    Ok(groups.memberships.len())
}

fn db_error(error: impl std::fmt::Display) -> EntityIngestionError {
    EntityIngestionError::DataError(error.to_string())
}
//! Concrete implementation of the repository

use std::str::FromStr;

use crate::{
    domain::{
        models::{
            entity_search::{
                EntitySearchRequest, FunderSearchMatch, FunderSearchResults, PhoneticRank,
                SearchMatchSource,
            },
            funder::{Funder, FunderId, FunderKind},
            search_similarity::SearchSimilarity,
        },
        repositories::funder_repository::{FunderRepo, FunderRepoError},
    },
    outbound::postgres::{ExposedDatabase, word_similarity_candidate_threshold},
};

impl FunderRepo for ExposedDatabase {
    async fn get_funders_by_text_search_score(
        &self,
        req: &EntitySearchRequest,
    ) -> Result<FunderSearchResults, FunderRepoError> {
        let mut tx = self
            .pool()
            .begin()
            .await
            .map_err(|e| FunderRepoError::DatabaseError(e.to_string()))?;
        sqlx::query!(
            "SELECT set_config('pg_trgm.word_similarity_threshold', $1, true)",
            word_similarity_candidate_threshold(req.strictness())
        )
        .fetch_one(&mut *tx)
        .await
        .map_err(|e| FunderRepoError::DatabaseError(e.to_string()))?;
        let rows = sqlx::query!(
            "
            WITH candidates AS (
                SELECT id FROM exposed.funders WHERE funder_name %> $1
                UNION
                SELECT funder_id FROM exposed.funder_aliases WHERE funder_alias %> $1
            ), scored AS (
                SELECT f.id, f.funder_name AS name, f.funder_kind AS kind,
                    word_similarity($1, f.funder_name) AS canonical_score,
                    a.funder_alias, a.alias_score
                FROM candidates c
                JOIN exposed.funders f ON f.id = c.id
                LEFT JOIN LATERAL (
                    SELECT funder_alias, word_similarity($1, funder_alias) AS alias_score
                    FROM exposed.funder_aliases WHERE funder_id = f.id
                    ORDER BY alias_score DESC, funder_alias COLLATE \"C\" ASC
                    LIMIT 1
                ) a ON true
            ), qualified AS (
                SELECT id, name, kind,
                    CASE WHEN alias_score > canonical_score THEN funder_alias END AS matched_alias,
                    GREATEST(canonical_score, COALESCE(alias_score, 0)) AS similarity_score
                FROM scored
                WHERE GREATEST(canonical_score, COALESCE(alias_score, 0)) >= $2
            ), grouped AS (
                SELECT DISTINCT ON (COALESCE(g.group_id, q.id)) COALESCE(g.group_id, q.id) AS id,
                    representative.funder_name AS name, representative.funder_kind AS kind,
                    CASE WHEN q.id <> COALESCE(g.group_id, q.id) THEN COALESCE(q.matched_alias, q.name)
                        ELSE q.matched_alias END AS matched_alias, q.similarity_score
                FROM qualified q LEFT JOIN exposed.funder_alias_groups g ON g.funder_id = q.id
                JOIN exposed.funders representative ON representative.id = COALESCE(g.group_id, q.id)
                ORDER BY COALESCE(g.group_id, q.id), q.similarity_score DESC, q.id
            )
            SELECT id AS \"id!\", name, kind, matched_alias, similarity_score, EXISTS(SELECT FROM qualified WHERE kind = $4) AS \"has_individual!\"
            FROM grouped
            ORDER BY similarity_score DESC, id
            LIMIT $3
            ",
            req.term(),
            req.strictness(),
            i64::from(req.max_entries()),
            FunderKind::Individual.as_ref(),
        )
        .fetch_all(&mut *tx)
        .await
        .map_err(|e| FunderRepoError::DatabaseError(e.to_string()))?;
        tx.commit()
            .await
            .map_err(|e| FunderRepoError::DatabaseError(e.to_string()))?;
        let has_qualifying_individual = rows.first().is_some_and(|row| row.has_individual);
        let matches = rows
            .into_iter()
            .map(|r| {
                let kind = r.kind.map_or(FunderKind::NotSpecified, |ref kind| {
                    FunderKind::from_str(kind).unwrap()
                });
                let funder = Funder::new(FunderId::new(r.id), r.name, kind);
                let score = SearchSimilarity::from(r.similarity_score.unwrap_or(0_f32));
                Ok((
                    FunderSearchMatch::new(
                        funder,
                        r.matched_alias.map_or(SearchMatchSource::Name, |name| {
                            SearchMatchSource::Alias { name }
                        }),
                    ),
                    score,
                ))
            })
            .collect::<Result<Vec<_>, FunderRepoError>>()?;
        Ok(FunderSearchResults {
            matches,
            has_qualifying_individual,
        })
    }
    async fn get_funders_by_phonetic_search(
        &self,
        req: &EntitySearchRequest,
    ) -> Result<Vec<(FunderSearchMatch, PhoneticRank)>, FunderRepoError> {
        let rows = sqlx::query!(r#"
            WITH names AS (
                SELECT id, funder_name AS candidate, NULL::text AS alias
                FROM exposed.funders
                WHERE funder_kind = $2 AND exposed.person_name_codes(funder_name) @> exposed.person_name_codes($1)
                UNION ALL
                SELECT f.id, a.funder_alias, a.funder_alias
                FROM exposed.funder_aliases a JOIN exposed.funders f ON f.id = a.funder_id
                WHERE f.funder_kind = $2 AND exposed.person_name_codes(a.funder_alias) @> exposed.person_name_codes($1)
            ), scored AS (
                SELECT names.*, correction.distance,
                       word_similarity(correction.corrected_query, candidate) AS similarity_score
                FROM names
                CROSS JOIN LATERAL (
                    SELECT string_agg(best.word, ' ' ORDER BY q.position) AS corrected_query,
                           sum(best.distance)::integer AS distance
                    FROM unnest(exposed.person_name_words($1)) WITH ORDINALITY AS q(word, position)
                    LEFT JOIN LATERAL (
                        SELECT cw.word, CASE
                            WHEN char_length(q.word) <= 255 AND char_length(cw.word) <= 255
                            THEN exposed.levenshtein_less_equal(q.word, cw.word, 1)
                            ELSE 2
                        END AS distance
                        FROM unnest(exposed.person_name_words(candidate)) AS cw(word)
                        WHERE exposed.soundex(cw.word) = exposed.soundex(q.word)
                        ORDER BY distance, cw.word COLLATE "C"
use crate::{
    domain::{
        models::{
            entity_details::{
                DeclarationCategory, DeclaredFunding, FunderAliasLink, FunderDeclaration,
                FunderFamilyLink, FunderFunding, FunderProfile, FunderReference, MemberDeclaration,
                MemberHistory, MemberProfile,
            },
            funder::{Funder, FunderId, FunderKind},
            parliament_member::MemberId,
        },
        repositories::entity_details::{EntityDetailsRepo, EntityDetailsRepoError},
    },
    outbound::postgres::ExposedDatabase,
};
use std::str::FromStr;

const CURRENCY_WHITESPACE: &str = "\t\n\u{000b}\u{000c}\r \u{0085}\u{00a0}\u{1680}\u{2000}\u{2001}\u{2002}\u{2003}\u{2004}\u{2005}\u{2006}\u{2007}\u{2008}\u{2009}\u{200a}\u{2028}\u{2029}\u{202f}\u{205f}\u{3000}\u{feff}";

impl EntityDetailsRepo for ExposedDatabase {
    async fn member(&self, id: MemberId) -> Result<Option<MemberHistory>, EntityDetailsRepoError> {
        let mut tx = self.pool().begin().await?;
        sqlx::query!("SET TRANSACTION ISOLATION LEVEL REPEATABLE READ, READ ONLY")
            .execute(&mut *tx)
            .await?;
        let row = sqlx::query!(
            "SELECT parliament_member_id, name, party_id, party_name, latest_membership_from, is_current_commons
             FROM exposed.members m WHERE parliament_member_id = $1", i32::try_from(id.value()).map_err(|error| EntityDetailsRepoError::DatabaseError(error.to_string()))?
        ).fetch_optional(&mut *tx).await?;
        let Some(row) = row else {
            return Ok(None);
        };
        let member = MemberProfile {
            id,
            name: row.name,
            party_id: row.party_id,
            party_name: row.party_name,
            membership_from: row.latest_membership_from,
            is_current_commons: row.is_current_commons,
        };
        let rows = sqlx::query!(
            "SELECT d.source_declaration_id, d.category_id, d.category_name, d.registration_date,
                e.id AS \"entry_id?\", e.amount, NULLIF(btrim(e.currency, $2), '') AS currency,
                e.payment_type, f.id AS \"funder_id?\", f.funder_name AS \"funder_name?\"
             FROM exposed.declarations d JOIN exposed.members m ON m.id = d.member_id
             LEFT JOIN exposed.funding_entries e ON e.source_declaration_id = d.source_declaration_id
             LEFT JOIN exposed.funders f ON f.id = e.funder_id
             WHERE m.parliament_member_id = $1
             ORDER BY d.registration_date DESC NULLS LAST, d.source_declaration_id DESC, e.id",
             i32::try_from(id.value()).map_err(|error| EntityDetailsRepoError::DatabaseError(error.to_string()))?,
             CURRENCY_WHITESPACE
        ).fetch_all(&mut *tx).await?;
        let mut declarations: Vec<MemberDeclaration> = Vec::new();
        for row in rows {
            if declarations
                .last()
                .is_none_or(|declaration| declaration.source_id != row.source_declaration_id)
            {
                declarations.push(MemberDeclaration {
                    source_id: row.source_declaration_id,
                    category: DeclarationCategory::from_source_id(row.category_id),
                    category_name: row.category_name,
                    registered_at: row.registration_date.map(registration_date).transpose()?,
                    entries: Vec::new(),
                });
            }
            if row.entry_id.is_some() {
                let funder = row
                    .funder_id
                    .zip(row.funder_name)
                    .map(|(id, name)| FunderReference {
                        id: FunderId::new(id),
                        name,
                    });
                if let Some(declaration) = declarations.last_mut() {
                    declaration.entries.push(DeclaredFunding {
                        funder,
                        amount: row.amount,
                        currency: row.currency,
                        payment_type: row.payment_type,
                    });
                }
            }
        }
        tx.commit().await?;
        Ok(Some(MemberHistory {
            member,
            declarations,
        }))
    }

    async fn funder_funding(
        &self,
        id: FunderId,
    ) -> Result<Option<FunderFunding>, EntityDetailsRepoError> {
        let mut tx = self.pool().begin().await?;
        sqlx::query!("SET TRANSACTION ISOLATION LEVEL REPEATABLE READ, READ ONLY")
            .execute(&mut *tx)
            .await?;
        let group_id = sqlx::query_scalar!(
            "SELECT COALESCE(g.group_id, f.id) AS \"group_id!\" FROM exposed.funders f
             LEFT JOIN exposed.funder_alias_groups g ON g.funder_id = f.id WHERE f.id = $1",
            id.value()
        )
        .fetch_optional(&mut *tx)
        .await?;
        let Some(group_id) = group_id else {
            return Ok(None);
        };
        let stored_member_ids = sqlx::query_scalar!(
            "SELECT funder_id AS \"funder_id!\" FROM exposed.funder_alias_groups WHERE group_id = $1
             UNION SELECT $1::uuid ORDER BY 1",
            group_id
        )
        .fetch_all(&mut *tx)
        .await?;
        let row = sqlx::query!(
            "SELECT f.funder_name, f.funder_kind,
                (SELECT CASE WHEN count(DISTINCT member.company_number) = 1
                    THEN min(member.company_number) END FROM exposed.funders member
                 WHERE member.id = ANY($2)) AS company_number
             FROM exposed.funders f WHERE f.id = $1",
            group_id,
            &stored_member_ids
        )
        .fetch_one(&mut *tx)
        .await?;
        let kind = row
            .funder_kind
            .as_deref()
            .map_or(Ok(FunderKind::NotSpecified), FunderKind::from_str)
            .map_err(|error| EntityDetailsRepoError::DatabaseError(error.to_string()))?;
        let aliases = sqlx::query_scalar!(
            "WITH names AS (
                SELECT funder_id, funder_alias FROM exposed.funder_aliases
                UNION SELECT id, funder_name FROM exposed.funders
             )
             SELECT DISTINCT funder_alias COLLATE \"C\" AS \"funder_alias!\" FROM names
             WHERE funder_id = ANY($1)
             ORDER BY funder_alias COLLATE \"C\"",
            &stored_member_ids
        )
        .fetch_all(&mut *tx)
        .await?;
        let member_ids = stored_member_ids
            .iter()
            .copied()
            .map(FunderId::new)
            .collect();
        let alias_links = sqlx::query!(
            "SELECT links.left_funder_id AS \"left_funder_id!\", links.right_funder_id AS \"right_funder_id!\",
                links.normalized_alias AS \"normalized_alias!\", links.left_alias AS \"left_alias!\", links.right_alias AS \"right_alias!\"
             FROM exposed.funder_alias_links links
             WHERE links.left_funder_id = ANY($1)
             ORDER BY links.left_funder_id, links.right_funder_id, links.normalized_alias COLLATE \"C\",
                links.left_alias COLLATE \"C\", links.right_alias COLLATE \"C\"", &stored_member_ids
        ).fetch_all(&mut *tx).await?.into_iter().map(|link| FunderAliasLink {
            left_funder_id: FunderId::new(link.left_funder_id),
            right_funder_id: FunderId::new(link.right_funder_id),
            normalized_alias: link.normalized_alias,
            left_alias: link.left_alias,
            right_alias: link.right_alias,
        }).collect();
        let family_links = sqlx::query!(
            "SELECT links.left_funder_id AS \"left_funder_id!\", links.right_funder_id AS \"right_funder_id!\",
                links.family_key AS \"family_key!\", links.left_name AS \"left_name!\", links.right_name AS \"right_name!\"
             FROM exposed.funder_family_links links
             WHERE links.left_funder_id = ANY($1)
             ORDER BY links.family_key COLLATE \"C\", links.left_funder_id, links.right_funder_id",
            &stored_member_ids
        ).fetch_all(&mut *tx).await?.into_iter().map(|link| FunderFamilyLink {
            left_funder_id: FunderId::new(link.left_funder_id),
            right_funder_id: FunderId::new(link.right_funder_id),
            family_key: link.family_key,
            left_name: link.left_name,
            right_name: link.right_name,
        }).collect();
        let profile = FunderProfile {
            funder: Funder::new(id, row.funder_name, kind),
            company_number: row.company_number,
            aliases,
            member_ids,
            alias_links,
            family_links,
        };
        let rows = sqlx::query!(
            "SELECT m.parliament_member_id, m.name, m.party_id, m.party_name,
                m.latest_membership_from, m.is_current_commons,
                d.source_declaration_id, d.category_id, d.category_name, d.registration_date,
                e.amount, NULLIF(btrim(e.currency, $2), '') AS currency, e.payment_type
             FROM exposed.funding_entries e
             JOIN exposed.declarations d ON d.source_declaration_id = e.source_declaration_id
             JOIN exposed.members m ON m.id = d.member_id
             WHERE e.funder_id = ANY($1)
             ORDER BY d.registration_date DESC NULLS LAST, d.source_declaration_id DESC, e.id",
            &stored_member_ids,
            CURRENCY_WHITESPACE
        )
        .fetch_all(&mut *tx)
        .await?;
        let mut declarations: Vec<FunderDeclaration> = Vec::new();
        for row in rows {
            if declarations
                .last()
                .is_none_or(|source| source.declaration.source_id != row.source_declaration_id)
            {
                declarations.push(FunderDeclaration {
                    member: MemberProfile {
                        id: row
                            .parliament_member_id
                            .to_string()
                            .parse::<MemberId>()
                            .map_err(|error| {
                                EntityDetailsRepoError::DatabaseError(error.to_string())
                            })?,
                        name: row.name,
                        party_id: row.party_id,
                        party_name: row.party_name,
                        membership_from: row.latest_membership_from,
                        is_current_commons: row.is_current_commons,
                    },
                    declaration: MemberDeclaration {
                        source_id: row.source_declaration_id,
                        category: DeclarationCategory::from_source_id(row.category_id),
                        category_name: row.category_name,
                        registered_at: row.registration_date.map(registration_date).transpose()?,
                        entries: Vec::new(),
                    },
                });
            }
            if let Some(source) = declarations.last_mut() {
                source.declaration.entries.push(DeclaredFunding {
                    funder: Some(FunderReference {
                        id,
                        name: profile.funder.name().to_owned(),
                    }),
                    amount: row.amount,
                    currency: row.currency,
                    payment_type: row.payment_type,
                });
//! Funder groups and their direct evidence, built from the surviving stored identities.

use std::collections::{BTreeMap, BTreeSet};

use serde::Deserialize;
use thiserror::Error;
use uuid::Uuid;

use super::{
    entity_details::{FunderAliasLink, FunderFamilyLink},
    funder::FunderId,
};

/// Canonical name and recorded aliases for one persisted identity.
pub struct GroupingFunder {
    /// Persistent identity.
    pub id: FunderId,
    /// Canonical source name.
    pub name: String,
    /// Exact recorded spellings.
    pub aliases: Vec<String>,
}

/// Complete replacement for the stored group membership and evidence.
pub struct FunderGroups {
    /// Every input identity belongs to exactly one component.
    pub(crate) memberships: Vec<(FunderId, FunderId)>,
    /// Direct equal-name evidence, without inferred transitive links.
    pub(crate) alias_links: Vec<FunderAliasLink>,
    /// Direct reviewed-family evidence, kept separate from equal-name evidence.
    pub(crate) family_links: Vec<FunderFamilyLink>,
}

#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
struct FamilyPolicy {
    version: PolicyVersion,
    families: Vec<ReviewedFamily>,
}

#[derive(Deserialize)]
#[serde(try_from = "u32")]
enum PolicyVersion {
    V1,
}

impl TryFrom<u32> for PolicyVersion {
    type Error = &'static str;

    fn try_from(version: u32) -> Result<Self, Self::Error> {
        match version {
            1 => Ok(Self::V1),
            _ => Err("unsupported reviewed funder family policy version"),
        }
    }
}

#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
struct ReviewedFamily {
    key: String,
    names: Vec<String>,
}

#[derive(Eq, PartialEq, Ord, PartialOrd)]
struct NormalizedName(String);

impl NormalizedName {
    fn parse(name: &str) -> Option<Self> {
        let name = name
            .split_whitespace()
            .collect::<Vec<_>>()
            .join(" ")
            .to_lowercase();
        (!name.is_empty()).then_some(Self(name))
    }
}

/// Invalid grouping input or reviewed policy.
#[derive(Debug, Error)]
pub enum FunderGroupingError {
    /// The versioned resource does not match its schema.
    #[error("invalid reviewed funder policy: {0}")]
    PolicyDecode(#[from] serde_json::Error),
    /// Policy names and keys must identify one reviewed family.
    #[error("invalid reviewed funder policy: {0}")]
    Policy(String),
    /// A persisted identity must occur exactly once in a snapshot.
    #[error("duplicate funder identity {0}")]
    DuplicateFunder(Uuid),
}

impl FamilyPolicy {
    fn parse(input: &str) -> Result<Self, FunderGroupingError> {
        let policy: Self = serde_json::from_str(input)?;
        let mut keys = BTreeSet::new();
        let mut names = BTreeSet::new();
        for family in &policy.families {
            if family.key.trim().is_empty() || !keys.insert(&family.key) {
                return Err(FunderGroupingError::Policy(
                    "family keys must be nonempty and unique".into(),
                ));
            }
            if family.names.is_empty() {
                return Err(FunderGroupingError::Policy(
                    "a reviewed family must have names".into(),
                ));
            }
            for name in &family.names {
                let normalized = NormalizedName::parse(name).ok_or_else(|| {
                    FunderGroupingError::Policy("reviewed names must be nonempty".into())
                })?;
                if !names.insert(normalized) {
                    return Err(FunderGroupingError::Policy(
                        "each normalized reviewed name must occur once".into(),
                    ));
                }
            }
        }
        Ok(policy)
    }
}

/// Builds connected components from exact normalized names and reviewed canonical names.
/// The smallest UUID represents a component, including singletons.
///
/// # Errors
/// Rejects duplicate identities and malformed or ambiguous reviewed policy.
pub fn build_funder_groups(
    funders: &[GroupingFunder],
) -> Result<FunderGroups, FunderGroupingError> {
    let policy = FamilyPolicy::parse(include_str!("funder_families.v1.json"))?;
    let mut ids = BTreeSet::new();
    for funder in funders {
        if !ids.insert(funder.id.value()) {
            return Err(FunderGroupingError::DuplicateFunder(funder.id.value()));
        }
    }
    match policy.version {
        PolicyVersion::V1 => {}
    }
    let mut components = Components::new(funders);
    let mut names = BTreeMap::<NormalizedName, BTreeMap<Uuid, BTreeSet<&str>>>::new();
    for funder in funders {
        for name in std::iter::once(&funder.name).chain(&funder.aliases) {
            if let Some(normalized) = NormalizedName::parse(name) {
                names
                    .entry(normalized)
                    .or_default()
                    .entry(funder.id.value())
                    .or_default()
                    .insert(name);
            }
        }
    }
    let mut alias_links = Vec::new();
    for (normalized, identities) in names {
        let identities: Vec<_> = identities.into_iter().collect();
        for (position, (left_id, left_names)) in identities.iter().enumerate() {
            for (right_id, right_names) in &identities[position + 1..] {
                components.join(*left_id, *right_id);
                for left in left_names {
                    for right in right_names {
                        alias_links.push(FunderAliasLink {
                            left_funder_id: FunderId::new(*left_id),
                            right_funder_id: FunderId::new(*right_id),
                            normalized_alias: normalized.0.clone(),
                            left_alias: (*left).into(),
                            right_alias: (*right).into(),
                        });
                    }
                }
            }
        }
    }
    let mut family_links = Vec::new();
    for family in policy.families {
        let reviewed: BTreeSet<_> = family
            .names
            .iter()
            .filter_map(|name| NormalizedName::parse(name))
            .collect();
        let mut members: Vec<_> = funders
            .iter()
            .filter(|funder| {
                NormalizedName::parse(&funder.name).is_some_and(|name| reviewed.contains(&name))
            })
            .collect();
        members.sort_by_key(|funder| funder.id.value());
        for (position, left) in members.iter().enumerate() {
            for right in &members[position + 1..] {
                components.join(left.id.value(), right.id.value());
                family_links.push(FunderFamilyLink {
                    left_funder_id: left.id,
                    right_funder_id: right.id,
                    family_key: family.key.clone(),
                    left_name: left.name.clone(),
                    right_name: right.name.clone(),
                });
            }
        }
    }
    family_links.sort_by_key(|link| {
        (
            link.family_key.clone(),
            link.left_funder_id.value(),
            link.right_funder_id.value(),
        )
    });
    let memberships = ids
        .iter()
        .map(|id| (FunderId::new(*id), FunderId::new(components.root(*id))))
        .collect();
    Ok(FunderGroups {
        memberships,
        alias_links,
        family_links,
    })
}

struct Components {
    parents: BTreeMap<Uuid, Uuid>,
}

impl Components {
    fn new(funders: &[GroupingFunder]) -> Self {
        Self {
            parents: funders
                .iter()
                .map(|funder| (funder.id.value(), funder.id.value()))
                .collect(),
        }
    }

    fn root(&mut self, id: Uuid) -> Uuid {
        let parent = self.parents[&id];
        if parent == id {
            return id;
        }
        let root = self.root(parent);
        self.parents.insert(id, root);
        root
    }

    fn join(&mut self, left: Uuid, right: Uuid) {
        let left = self.root(left);
        let right = self.root(right);
        self.parents.insert(left.max(right), left.min(right));
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn funder(id: u128, name: &str, aliases: &[&str]) -> GroupingFunder {
        GroupingFunder {
            id: FunderId::new(Uuid::from_u128(id)),
            name: name.into(),
            aliases: aliases.iter().map(|name| (*name).into()).collect(),
        }
    }

    #[test]
    fn connected_components_keep_direct_evidence_and_split_after_bridge_removal() {
        let mut funders = vec![
            funder(3, "Gamma", &["Bridge two", "ALPHA"]),
            funder(1, "Alpha", &["Bridge one"]),
            funder(2, "Beta", &["  BRIDGE\tONE  ", "Bridge two"]),
            funder(4, "Separate", &["  "]),
        ];
        let groups = build_funder_groups(&funders).unwrap();
        assert_eq!(
            groups
                .memberships
                .iter()
                .map(|(id, group)| (id.value().as_u128(), group.value().as_u128()))
                .collect::<Vec<_>>(),
            [(1, 1), (2, 1), (3, 1), (4, 4)]
        );
        assert_eq!(groups.alias_links.len(), 3);
        assert!(groups.family_links.is_empty());
        funders[0].aliases.clear();
        let groups = build_funder_groups(&funders).unwrap();
        assert_eq!(groups.memberships[2].1.value(), Uuid::from_u128(3));
        assert_eq!(groups.alias_links.len(), 1);
